INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1d770d85-cef8-4f12-a53b-e33eba632c83', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "9d3e9f6a-2516-4cd4-a314-2bc80fffb9bd", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "4070ddea-62b3-45bd-b4dc-ebaedfcfa7e4", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "e6c2163d-5a8b-42af-8c2d-e8778cbe8748", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "a0ab986c-2f4c-4257-9b85-4171a3ab03a7", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "7293fc96-83c4-4737-a9b5-ec6c42715845", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "66556a1b-4eeb-437a-ad6f-65de46c83f64", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "f848ce9f-9476-4926-bc47-68313001328d", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "8998f7f8-7280-45be-be87-7765aa23c66e", "text": "Számok összeadására", "isCorrect": false}, {"id": "e7339803-113f-4ca1-ade7-a57316ff0136", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "be592aab-558e-48a4-9ee1-d4e1ccb2c20f", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "725adf4c-07ec-4b59-89f4-bd74a8aa45c2", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c2b2394f-c0ed-4243-a8d4-c8d97c8a2e02", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "f39d5fa0-4d12-4f73-9776-845c55fed6ef", "text": "Igaz", "isCorrect": true}, {"id": "fad2aba4-b3dc-4d13-afde-f79aab5ed162", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ba2ec29-4656-429e-9c08-a4b670171788", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "643d62d8-5e1e-4fcc-81e8-514e96c9a4ca", "text": "Igaz", "isCorrect": true}, {"id": "36fe1fa7-3415-4f3e-89b7-220ab2eac832", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4abb78b6-310d-40ec-bbf8-e48ae91808f0", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "4db368e2-7000-4de3-ab8d-217d5921fe32", "text": "Igaz", "isCorrect": true}, {"id": "e67d0b6e-c9b0-4ae5-87a1-ffb91f918c36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f38bf064-28b3-4eb2-853e-28b0cbf718ad", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('13a1c91b-81ba-44ca-93e2-e1b021977193', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "7fad321a-faa5-4a18-8ca0-38ecf8dd47bd", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "2ce2fe45-e04a-4a5b-9b32-6822f2966ec2", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "05301c3e-a70b-4d46-850e-803edbaf3746", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "a39b25df-8992-44fd-b8cb-8b6983d2374e", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "d6345dc0-7589-44ae-84a1-7fdfc5b3e736", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "0a8ebd84-4387-48ce-a71c-1da03fd86be4", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "287ba4ec-7e67-4023-b911-c127334f4eb8", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "617faf37-cf13-4f7f-b482-30d2cc6d40f7", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "d6dea70e-ad53-4f11-8840-e4f20c4d8028", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "607125c4-242c-490d-aa66-e200acdfbf4e", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "b99fa181-9535-4341-a740-101e75685d02", "text": "Igaz", "isCorrect": true}, {"id": "a834d298-a574-4e80-be45-679c393871eb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "81fc1c98-c663-482a-8868-32b9bd90500d", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "22c38e00-4069-4bfe-a9ce-6ddd888ba000", "text": "Igaz", "isCorrect": true}, {"id": "a394f35c-82c5-48d5-9fc8-63ac319d9818", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3622c1dc-4d8f-489b-bf8d-22625aeecbe8', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "e91a3af2-ef09-4273-a8db-9e7061aca17a", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "c90b0813-baee-4ecb-b185-4e7eb5de3640", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "403b7601-f0fb-4185-9a59-c2affc9cbc00", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "47024105-d5d4-4217-b473-12baa73a418c", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "7b14a989-2fb5-48cf-a980-0b42cc79f20d", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "6414d938-e7d7-4a17-9430-d786811eb95d", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "389fe96b-7ce4-4199-8c77-3bd95d9efb6d", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "3e623877-f54a-408e-a5b1-331569e29828", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "07cfd4ab-33a0-4444-b39c-42b60bcc5a42", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "a11fdeed-76a7-49dc-81c4-9e0451b8e6bc", "text": "Igaz", "isCorrect": true}, {"id": "dd0b4340-26a4-49a3-9fea-19b2167466a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "94db1e59-05a9-4d65-aec9-3b608069e424", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "ce790221-d815-4a29-a157-72f1acb2bfee", "text": "Igaz", "isCorrect": true}, {"id": "4236c19f-e745-4e99-aecf-5373696896af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15c25a3c-e0a0-41e2-a152-5b9ee9f6a944", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fbf6e261-876d-47fe-a864-f3b709e4b377', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "af5f1035-b050-4f7c-93fa-316377a3b149", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "410f417f-8641-436e-b6ef-2380b24ae089", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "d330f1a2-1067-482e-9c4e-dacce1f6c031", "text": "1 a 2-ből", "isCorrect": false}, {"id": "9a9745e9-b74e-4e67-aa6d-3ff8e764843d", "text": "100%", "isCorrect": false}, {"id": "e43ba007-13ec-411d-a9a6-dfc875f7dc8c", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "8d7348f7-a8c9-410f-a7a8-d2fed7ab5f6c", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "492294b1-0b53-4e43-a300-e747ba78411e", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "0b69fe59-a00e-4c0f-a6e9-6a5375babf02", "text": "1/6", "isCorrect": false}, {"id": "90d62a3e-32a8-4c95-84f9-bac82066495d", "text": "2/6", "isCorrect": false}, {"id": "5e92cfdd-cfb3-4408-8c2c-33762d999969", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "8bcf31c7-06b2-48af-9db3-43bcdee93f70", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "bddb3fcb-44f8-455a-ace1-6a81cdf324ae", "text": "Igaz", "isCorrect": true}, {"id": "1272dacd-e45f-4f27-b3be-a37f6e30f099", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92bf09fc-b087-4e78-8599-1fc3198f85e5", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "147bc535-9bd3-4263-b71a-1357d361e439", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "531d2fd9-6c4f-4fe1-8d61-d749ed35fd13", "text": "Biztos esemény", "isCorrect": false}, {"id": "fcf03fa5-52bb-46e5-a1cf-221cd8909ba8", "text": "Lehetséges", "isCorrect": false}, {"id": "2cfdd125-b357-42f6-9ff3-27a316829209", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "fbf25722-8e3d-4da2-9b39-83b534c1a073", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "1ea29f46-6edb-4ec9-8487-1608f164f97c", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "1d16e419-bb97-48aa-aa43-7104f55fc8f3", "text": "Lehetetlen", "isCorrect": false}, {"id": "2253ff10-4511-460a-8c4a-d23c46e72279", "text": "Kétes", "isCorrect": false}, {"id": "4bc34ac1-fff5-4772-a064-5e29635a0826", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "e51a7806-de62-4bc6-9b25-f6b53dc4a290", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "67fa022d-0d18-4de8-9dd0-0ba59c432906", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "82215c96-8850-4883-bd66-e72dd0258ce7", "text": "Igaz", "isCorrect": true}, {"id": "ee19a9d9-9fff-4b6e-acde-6258df18ba5e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0a60503e-c008-457e-bd54-2727b1c4825c', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "96430d25-b6b5-478b-8cf5-3656276f66f3", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "02167556-e75d-4bb4-b86f-d26770cfa34d", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "f3a5ad85-26c1-4f10-be61-4fb8c2047010", "text": "1/4", "isCorrect": false}, {"id": "371b14a0-cf5c-468c-9f63-8116786310d3", "text": "100%", "isCorrect": false}, {"id": "9a9f0dd2-b2ac-4382-8ad3-122804a90b0a", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "7d5ef1c2-3add-42a2-a49b-387ccadf29e4", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "c128466d-cb23-4d8b-9a66-8c9fe81cc3f2", "text": "Igaz", "isCorrect": true}, {"id": "5dfba3ce-e8fe-4db1-9b08-171af0adc7cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b2199db-51ad-4f07-b20b-84bf31f4bf94", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e7abf008-14fc-471a-9c57-0642b1cf6609", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "5cf88175-fdb1-4309-8671-3af28a86eddf", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "de3afe60-0d9f-421b-a597-64746246d7ee", "text": "Igaz", "isCorrect": true}, {"id": "f17fc542-9358-4ac0-b2c9-45a42faba805", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6cf6f339-5d02-4271-aab1-e111c6db94cc", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "1f5c3a97-9ba3-44c9-8474-e8f008a1af23", "text": "Igaz", "isCorrect": true}, {"id": "4875ce86-8d2d-49b1-99a8-46929259f5ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "22c91e89-c277-4e04-8b74-77df8a0452bd", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "695797ba-196a-4a4a-b4f1-7c132a2baece", "text": "Igaz", "isCorrect": true}, {"id": "fd57a36d-7a91-4297-b7f5-37f6faaf58ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fde469bc-69d7-420f-b36d-31cda2988f36', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "330f8f1c-ca98-4afc-ad2d-cb0cc8d07f1e", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "63f515d4-8dbf-4d81-9ff9-78271d7c6e0f", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "c3954b46-032f-451b-b75c-24934d272dfe", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "8375de90-cf7f-4793-bcfd-118ddb5395d7", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "f7efa0ca-5bc6-4878-8ba8-4447719b02c4", "text": "Igaz", "isCorrect": true}, {"id": "b5e5180b-ed1b-413c-a95b-e893b7903310", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9f38302e-fd50-417b-8644-235f653fbe54", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "f1fbdf9d-c1a0-4a24-80ab-47efce2123e6", "text": "Igaz", "isCorrect": true}, {"id": "62d9e6af-b83e-402a-ad21-55c49bd6063e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d4c7345-3f51-48ed-ba98-2e0b929c24e6", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "746dffe5-675c-4609-b164-828835667fb3", "text": "Vonaldiagram", "isCorrect": true}, {"id": "29007238-d234-43d9-a447-e9c7491a28f7", "text": "Kördiagram", "isCorrect": false}, {"id": "ddb4312f-3cab-4b8d-9a10-bcc47a29dc90", "text": "Pontdiagram", "isCorrect": false}, {"id": "f8b2a5d3-2b64-4d20-841a-bc81d200bb2f", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "54ba245c-b25b-4b3b-aad9-e2e366b96d4c", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a27927fa-7c91-402c-a5d7-1b11fb807b12', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "c1c4a8fc-4067-4f44-86a5-ab9f97ff8d4f", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f4b628cd-433f-4705-8f58-575cc2bee793", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "2fd0392d-e12b-4910-b1d8-d3a7fb817ee6", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "0b2a3c5c-13b8-48b4-9601-549c039458a4", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "1e512a99-ae55-43f5-86ea-b57f2b0c905d", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "d24a004e-bc77-4f64-951a-6d2932416b2b", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "e3318a0a-512c-4520-9e4a-140d0200649d", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "b0509cfb-d842-4697-a025-6303041859d5", "text": "Biztos esemény", "isCorrect": false}, {"id": "adb627c0-7265-40aa-ba56-fe3d6013f103", "text": "Lehetséges", "isCorrect": false}, {"id": "5df90086-4571-411e-a25d-beb24f531205", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "895aceef-4709-47d5-b1d4-5387ac492733", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "8532b2e2-f1d4-4cca-87ae-cd2cc599f6c2", "text": "Biztos esemény", "isCorrect": true}, {"id": "c0927a31-df1c-491b-ae9c-054140929b5a", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "afc923cf-4348-462e-80af-6433b18bebf5", "text": "Ritka", "isCorrect": false}, {"id": "c057223b-cc82-4f79-9caa-a61d4cff84dd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "256301c9-4a07-45e0-8f14-d6036df047cc", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "68ddcc98-5131-4b8c-a365-d3fdd2ddda1b", "text": "Igaz", "isCorrect": true}, {"id": "6b3981e9-7596-4ed0-b964-8e1359bf5bca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2562200-6806-4a78-bc1b-6ce2a87f27fc", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "f4cc3296-8a42-474f-b6b5-b3e474cd918c", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "4dfa0df6-8728-49af-a0ab-34f113ebe293", "text": "Igaz", "isCorrect": true}, {"id": "170814c5-b556-434b-8c3d-5e6256ba95e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5e70ba71-a53c-423d-8e7e-8b6bb6e587ae', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "f069cf78-804b-47e5-bbb2-1268f3371587", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "875f2da1-a0a2-49b9-a779-0af1def5bf59", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "f9e6233c-bb15-4176-b065-ebf497c89e1d", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "22d083ff-6409-4df3-b429-591ce70749f0", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "96439b7f-9dd4-4b8c-b0fd-1c53d910d037", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "b46d978b-5618-4158-b58b-5a6fb7daed1b", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "daa17db1-a7fa-43da-b0d9-df12f4c12f75", "text": "Igaz", "isCorrect": true}, {"id": "54993359-6cd1-4310-9da9-ed6d11691021", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfb49b15-609a-4b1e-bbe7-a02fcfa7dc45", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "be79d511-c195-45b5-8cdc-baf1d77d0074", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "37bf70b6-9768-47e1-a3ac-570cd27bdba9", "text": "Igaz", "isCorrect": true}, {"id": "7cda8e20-0521-4c61-ae91-7a66d9e5c631", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f7f3fec-2bc5-4a0d-8fd8-d67f54fc93f4", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "06480b67-080f-4134-a1e2-22934b039e89", "text": "Igaz", "isCorrect": true}, {"id": "a60c7e5b-b76c-44dd-a9c3-6a7171478c81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ddb68b16-9b8f-418a-b768-36a2c9a86a88", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f925003b-aa86-4009-b485-17d9658322d1", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "aa377af4-1015-4c0e-8c43-67510941376d", "text": "Igaz", "isCorrect": true}, {"id": "62ab01b2-3ffc-4561-ab92-a9fb4ff2c9a5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('202338b1-10bf-4138-ba41-e26f4e8cdcff', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "910283de-e4f9-4a8c-9629-a4f19717bb9a", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "39a0f980-dc3c-4549-836b-8c65e2bb4842", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "0f242f0a-31b3-4058-95ee-655ee65ddfbb", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "733a5158-0c9f-4538-a49f-9da9e8662b74", "text": "A büntetés", "isCorrect": false}, {"id": "772aced3-bcf6-4770-9875-e5a353e48fbb", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "99d9ef34-3198-4575-aa0c-c4b7b802273f", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "38845b2c-ebbb-4a47-98b3-e89c7d4f43da", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "fe8c55d7-fde6-4744-8398-d68fb5d354f4", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "a7db12b4-a8a5-45cb-a760-66e3eea59561", "text": "Igaz", "isCorrect": true}, {"id": "04cdd05d-e299-499d-825d-ba35685cd83d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0fabf7e9-c098-4023-9def-90877a5378ca", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "23f1f6fa-bb94-4cbc-b7cc-cb69fc3c9f05", "text": "Igaz", "isCorrect": true}, {"id": "7614fff7-6566-4260-af5b-a351f1b73a6a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "401563a1-a294-4291-9adc-642a929f49f6", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "4a7e648e-bd72-49c0-8a37-f879e46fc893", "text": "Igaz", "isCorrect": true}, {"id": "fe3abdf6-1392-4094-9dc1-9a9226eb9ee2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5645ae7c-7380-4ea0-83b6-43e667d701f5", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('aea742b3-207f-4536-8159-7a7cee3d03c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "e6104729-9c2c-4233-9d94-0a254e827640", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "3ad8e31c-08d8-4ef1-a6ad-40c19fe439dc", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "96e2fbf5-bd86-4cf2-b381-616e223c25a1", "text": "A bankjegy színe", "isCorrect": false}, {"id": "999f95f4-e651-4354-8bbc-45d29509e4a0", "text": "A pénz súlya", "isCorrect": false}, {"id": "80ddf031-9819-44fa-9ea9-637b0cfbb44b", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "6e7d73d9-b47b-4d31-af4a-aea003e794a1", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "fc373bc7-08e8-4324-a2e3-dbd5b3284cde", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "2420a6ed-685d-439d-91b0-944880f4ddf4", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "401f22ed-97b9-4da3-8f14-8d1a250c03aa", "text": "Igaz", "isCorrect": true}, {"id": "42182f3c-ff59-41e7-a359-e9a1e1362c0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f4daea39-1b0e-435d-955a-db0c83dc43f4", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "7a58b27e-e159-479d-bc8d-f32342990c3e", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "f543fe33-2b64-4b81-868e-eaa9e23e7d78", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "102ada0c-bcbe-4b66-8041-f3fc0170f4bb", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "bbb6fcf1-8445-4f73-a670-75129c23129a", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "303d24ee-0fdb-4037-a37b-d1e6af828fa1", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "9d6e8047-310d-4591-8929-fb994bed0264", "text": "Igaz", "isCorrect": true}, {"id": "940e9884-aff9-4f7b-8f19-045b5a951acf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9958ee27-619f-4984-b794-7367cc922e44", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW());